    articleView.dataset.vol = id;
    document.body.classList.toggle('article-one-pattern-active', true);
    document.getElementById('art-vol').textContent = a.vol;
    document.getElementById('art-title').textContent = a.title;
    document.getElementById('art-author').textContent = '文字｜' + (a.author || '〔記者姓名〕');
