                <div class="article-preview-copy">
                  <div class="article-preview-meta"><span class="article-preview-kind" data-preview-kind></span><span class="article-preview-source" data-preview-source></span></div>
                  <h4 class="article-preview-title" data-preview-title></h4>
                  <p class="article-preview-desc" data-preview-desc></p>
                  <span class="article-preview-open">查看原文 ↗</span>
                </div>
